// Breaking Bellman content, version 2: the update rule is a sentence of plain words you can change.
// Every number quoted here comes from a run logged in EXPERIMENTS.md (Simulation).
window.CONTENT = (function () {
  // ---- the words of the sentence. options: [value, chip text, one-line meaning]
  const words = {
    store: { q: 'Where do the estimates live?', options: [
      ['table', 'a table', 'One number per state and action. What one cell learns never reaches its neighbors.'],
      ['net', 'a network', 'A small neural network computes all estimates from the state. Similar states share what they learn.'],
    ] },
    eps: { q: 'Does it sometimes act at random?', options: [
      [true, 'sometimes at random (ε)', 'With probability ε it takes a random action instead of the best one.'],
      [false, 'never at random', 'It always takes the action with the best estimate.'],
    ] },
    ucb: { q: 'Does it add a bonus for actions tried few times?', options: [
      [false, 'no bonus', 'Only the estimate counts.'],
      [true, 'a bonus for few tries', 'Adds c·√(ln t / n) to an action tried n times out of t, so a rarely tried action gets a push.'],
    ] },
    optimistic: { q: 'What do the estimates start at?', options: [
      [false, '0', 'Every estimate starts at 0.'],
      [true, '+5 (high)', 'Every estimate starts high, so an untried action looks good until it is tried.'],
    ] },
    data: { q: 'Which moves does it learn from?', options: [
      ['latest', 'the move just made', 'Each update uses the newest move only, then forgets it.'],
      ['replay', 'random old moves from memory', 'It keeps the last moves in a memory and learns from random batches of 32 of them.'],
    ] },
    memory: { q: 'How many old moves does the memory keep?', options: [
      [1000, '1 000', 'A short memory: mostly recent moves.'], [10000, '10 000', 'The default.'], [50000, '50 000', 'A long memory: many moves from older policies.'],
    ] },
    step: { q: 'How far does each update move the estimate?', options: [
      ['const', 'a fixed share (α)', 'Moves a fixed share α of the way to the target. Recent targets count more than old ones.'],
      ['avg', 'to the average of its targets', 'Step 1/n for the n-th update of that cell: the estimate is the plain average of all targets it saw.'],
    ] },
    nstep: { q: 'How many real rewards before it trusts a guess?', options: [
      [1, '1 real reward', 'Uses the next reward, then a guess of the value of the next state.'],
      [2, '2 real rewards', 'Uses 2 rewards, then a guess.'], [4, '4 real rewards', 'Uses 4 rewards, then a guess.'], [8, '8 real rewards', 'Uses 8 rewards, then a guess.'],
      [0, 'all rewards to the end', 'Waits until the episode ends and uses the sum of all rewards. No guess at all.'],
    ] },
    agg: { q: 'Which next action does the guess use?', options: [
      ['max', 'the best next action', 'The action with the highest estimate in the next state.'],
      ['taken', 'the action really taken next', 'The action the learner really took in the next state, random tries included.'],
      ['mean', 'the average next action', 'The average over next actions, weighted by how often the learner takes each one.'],
      ['min', 'the worst next action', 'The action with the lowest estimate in the next state.'],
    ] },
    picker: { q: 'Which estimate chooses that next action?', options: [
      ['live', 'the live estimate', 'The estimate that is being trained right now.'],
      ['frozen', 'a frozen copy', 'An old copy of the estimate. It is refreshed only every few hundred updates.'],
      ['second', 'a second estimate', 'An independent twin. Each update trains one twin, chosen at random.'],
    ] },
    scorer: { q: 'Which estimate gives the value of that action?', options: [
      ['live', 'the live estimate', 'The estimate that is being trained right now.'],
      ['frozen', 'a frozen copy', 'An old copy of the estimate, refreshed every few hundred updates.'],
      ['second', 'a second estimate', 'An independent twin, trained on other updates.'],
      ['minpair', 'the smaller of live and second', 'Asks both twins and keeps the lower value.'],
    ] },
    sync: { q: 'How often is the frozen copy refreshed?', options: [
      [10, 'every 10 updates', 'Almost live.'], [50, 'every 50 updates', 'Often.'], [250, 'every 250 updates', 'The default.'], [1000, 'every 1000 updates', 'Rarely: very stale.'],
    ] },
  };

  const base = { store: 'table', eps: true, ucb: false, optimistic: false, data: 'latest', memory: 10000, step: 'const', nstep: 1, agg: 'max', picker: 'live', scorer: 'live', sync: 250 };
  const cfg = (o) => Object.assign({}, base, o);

  // ---- what the literature calls some sentences. keys: the words that define the method
  // (an array means any of these values). world: 'bandit' or '!bandit'. First match wins.
  const R = (id, name, card, world, keys, blurb) => ({ id, name, card, world, keys, blurb });
  const recipes = [
    R('greedy-bandit', 'Greedy averages', null, 'bandit', { eps: false, ucb: false, optimistic: false }, 'An average per machine; always the best one.'),
    R('ucb-bandit', 'UCB', 'ucb', 'bandit', { ucb: true, eps: false }, 'A bonus for machines with few tries.'),
    R('opt-bandit', 'Optimistic initial values', 'optimism', 'bandit', { optimistic: true, eps: false, ucb: false, step: 'const' }, 'High start values make every machine worth a try.'),
    R('eps-bandit', 'ε-greedy', 'egreedy', 'bandit', { eps: true, ucb: false }, 'Mostly the best machine, sometimes a random one.'),
    R('mc-table', 'Monte Carlo control', 'mc', '!bandit', { store: 'table', nstep: 0 }, 'A table moved toward the full return when the episode ends.'),
    R('mc-net', 'Monte Carlo with a network', null, '!bandit', { store: 'net', nstep: 0 }, 'No guess: the network learns full returns.'),
    R('clipped', 'Clipped double Q', 'clipped', '!bandit', { agg: 'max', scorer: 'minpair' }, 'The smaller of two estimates scores the next action.'),
    R('ddqn', 'Double DQN', 'ddqn', '!bandit', { store: 'net', data: 'replay', agg: 'max', picker: 'live', scorer: 'frozen', nstep: 1 }, 'DQN whose frozen copy scores the action the live network chooses.'),
    R('dqn', 'DQN', 'dqn', '!bandit', { store: 'net', data: 'replay', agg: 'max', picker: 'frozen', scorer: 'frozen', nstep: 1 }, 'A network held steady by replay and a frozen copy.'),
    R('doubleq', 'Double Q-learning', 'doubleq', '!bandit', { agg: 'max', picker: 'live', scorer: 'second', nstep: 1 }, 'One estimate chooses the next action, the other scores it.'),
    R('expsarsa', 'Expected Sarsa', 'expsarsa', '!bandit', { agg: 'mean', scorer: 'live', nstep: 1 }, 'The guess averages over next actions, as often as the learner takes them.'),
    R('sarsa', 'Sarsa', 'sarsa', '!bandit', { agg: 'taken', scorer: 'live', nstep: 1, data: 'latest' }, 'The guess uses the action really taken next.'),
    R('nstep', 'n-step TD', 'nstep', '!bandit', { nstep: [2, 4, 8] }, 'Several real rewards, then a guess.'),
    R('naive-net', 'Naive neural Q-learning', null, '!bandit', { store: 'net', data: 'latest', agg: 'max', picker: 'live', scorer: 'live', nstep: 1 }, 'A network that learns from targets it makes itself, one move at a time.'),
    R('qlearning', 'Q-learning', 'qlearning', '!bandit', { store: 'table', agg: 'max', picker: 'live', scorer: 'live', nstep: 1 }, 'After every step, move toward the reward plus the best next estimate.'),
  ];

  // failures are discoveries too: they open when the autopsy shows them
  const failures = [
    { card: 'lockin', when: (a, c) => c.world === 'bandit' && a.symptoms.some((s) => s.id === 'lockIn' && s.level === 'bad') },
    { card: 'noend', when: (a, c) => c.world === 'cliff' && c.parts.nstep === 0 && a.summary.finalReturn <= -150 },
    { card: 'triad', when: (a, c) => (c.parts.family || 'value') === 'value' && c.parts.store === 'net' && c.parts.nstep > 0
      && (c.parts.data === 'replay' || (c.parts.eps && ['max', 'min'].includes(c.parts.agg)) || (c.parts.agg === 'mean' && c.parts.picker !== 'live'))
      && a.symptoms.some((s) => s.id === 'diverge' && s.level === 'bad') },
    { card: 'maxbias', when: (a) => a.symptoms.some((s) => s.id === 'mirage' && s.level === 'bad') },
  ];

  const SB = 'Sutton and Barto (2018), <i>Reinforcement Learning: An Introduction</i>, 2nd ed.';
  const Q = (loc, quote) => `<p class="small"><b>${loc}:</b> ${quote}</p><p class="small muted">Quote checked against the source text (15 Oct 2026).</p>`;
  const cards = {
    lockin: { kind: 'failure', name: 'Lock-in', short: 'Lock-in', status: 'checked', paper: SB + ', section 2.3.',
      fixes: 'A failure, not a method: greedy never retries an action whose estimate fell behind.',
      stillWrong: 'In this page: best machine 33% of the time with noise, 24% without noise (300 runs each, Simulation).',
      evidence: Q('Sutton and Barto 2018, section 2.3', '“the greedy method found the optimal action in only approximately one-third of the tasks. In the other two-thirds, its initial samples of the optimal action were disappointing, and it never returned to it.”') },
    egreedy: { name: 'ε-greedy', short: 'ε-greedy', status: 'checked', paper: SB + ', section 2.2.', review: 'bandit',
      fixes: 'Lock-in: every action keeps a small chance to be tried again.',
      stillWrong: 'It explores at the same rate forever, and its random tries ignore what it knows. In this page: 78% best machine (300 runs, Simulation).',
      evidence: Q('Sutton and Barto 2018, section 2.3', '“The ε-greedy methods eventually performed better because they continued to explore and to improve their chances of recognizing the optimal action.”') },
    optimism: { name: 'Optimistic initial values', short: 'Optimism', status: 'checked', paper: SB + ', section 2.6.', review: 'bandit',
      fixes: 'Lock-in, at the start only: each disappointing machine drops below the untried ones.',
      stillWrong: 'The push to explore is used up early, so it cannot follow a machine that changes later. With the step "to the average" the first pull erases the high start.',
      evidence: Q('Sutton and Barto 2018, section 2.6', '“it is not well suited to nonstationary problems because its drive for exploration is inherently temporary.”') },
    ucb: { name: 'Upper confidence bound (UCB)', short: 'UCB', status: 'checked', paper: SB + ', section 2.7, after Auer, Cesa-Bianchi and Fischer (2002).', review: 'bandit',
      fixes: 'Random tries waste pulls on machines already known to be bad; UCB tries what is still uncertain.',
      stillWrong: 'It needs a count per state and action, so it does not carry over easily to large state spaces. In this page: lowest total regret, 152 (300 runs, Simulation).',
      evidence: Q('Sutton and Barto 2018, section 2.7 and notes', '“UCB often performs well, as shown here, but is more difficult than ε-greedy to extend beyond bandits to the more general reinforcement learning settings”. UCB was “first developed by Auer, Cesa-Bianchi and Fischer (2002).”') },
    mc: { name: 'Monte Carlo control', short: 'Monte Carlo', status: 'checked', paper: SB + ', chapter 5.', review: 'mirage',
      fixes: 'A one-step bandit ignores the future: the full return credits each action with all the rewards that follow it.',
      stillWrong: 'It learns only when an episode ends. On the cliff, no episode reached the goal within 200 steps, so it never learned (20 runs, Simulation).',
      evidence: Q('Sutton and Barto 2018, chapter 5', '“Only on the completion of an episode are value estimates and policies changed.”') },
    noend: { kind: 'failure', name: 'No end, no signal', short: 'No end', status: 'checked', paper: SB + ', Example 6.5.',
      fixes: 'A failure: the full return arrives only at the end, and the time limit cuts the walk before the goal.',
      stillWrong: 'In this page a longer limit (500) and more random tries (ε 0.3) both still failed (20 runs each, Simulation).',
      evidence: Q('Sutton and Barto 2018, Example 6.5', '“Monte Carlo methods cannot easily be used here because termination is not guaranteed for all policies. If a policy was ever found that caused the agent to stay in the same state, then the next episode would never end.”') },
    qlearning: { name: 'Q-learning', short: 'Q-learning', status: 'checked', paper: 'Watkins (1989), PhD thesis, as cited in ' + SB + ', section 6.5.', review: 'cliff',
      fixes: 'The full return needs the episode to end: Q-learning learns after every step from its own estimate of the next state.',
      stillWrong: 'It learns the value of the best path, not of the path it walks while it explores: on the cliff it keeps falling, 0.32 falls per episode (Simulation). A table needs one cell per state.',
      evidence: Q('Sutton and Barto 2018, section 6.5 and Example 6.6', '“off-policy TD control algorithm known as Q-learning (Watkins, 1989)”. On the cliff: “Q-learning learns values for the optimal policy, that which travels right along the edge of the cliff. Unfortunately, this results in its occasionally falling off”.') },
    sarsa: { name: 'Sarsa', short: 'Sarsa', status: 'checked', paper: 'Rummery and Niranjan (1994), as cited in ' + SB + ', section 6.4.', review: 'cliff',
      fixes: 'Q-learning plans as if it never acts at random, so it walks the edge. Sarsa values the action it really takes next, random tries included.',
      stillWrong: 'Its target depends on one random next action, so it is noisy. In this page: 0.06 falls per episode, but the greedy path was unstable, mean score −82 (sd 47, 20 runs, Simulation).',
      evidence: Q('Sutton and Barto 2018, Example 6.6 and notes to section 6.4', '“Sarsa, on the other hand, takes the action selection into account and learns the longer but safer path through the upper part of the grid.” “The Sarsa algorithm was introduced by Rummery and Niranjan (1994).”') },
    expsarsa: { name: 'Expected Sarsa', short: 'Exp. Sarsa', status: 'checked', paper: SB + ', section 6.6.', review: 'cliff',
      fixes: 'The Sarsa target depends on one random next action; Expected Sarsa averages over the next actions instead.',
      stillWrong: 'It needs the probability of every next action: easy for ε-greedy over a few actions, hard for large or continuous action sets. It keeps most of the maximization bias of the level "The mirage": with ε = 0.1, 91% of the weight of its guess still sits on the best-looking next action, so it took the losing door in 59% of episodes at the worst point (300 runs, Simulation). On the cliff: −15 and 0.04 falls per episode (20 runs, Simulation).',
      evidence: Q('Sutton and Barto 2018, section 6.6', '“just like Q-learning except that instead of the maximum over next state–action pairs it uses the expected value, taking into account how likely each action is under the current policy.” “Expected Sarsa retains the significant advantage of Sarsa over Q-learning on this problem.”') },
    nstep: { name: 'n-step TD', short: 'n-step', status: 'checked', paper: SB + ', chapter 7.', review: 'cliff',
      fixes: 'One-step guesses pass information back slowly; full returns need an end and are noisy. n real rewards, then a guess, sits between the two.',
      stillWrong: 'Each row needs the next n rewards, so learning waits n steps; with replay those rewards come from an older policy. In this page: 4 rewards, replay and a frozen copy balanced CartPole at 199 of 200 (3 seeds, Simulation).',
      evidence: Q('Sutton and Barto 2018, chapter 7 introduction', '“n-step methods span a spectrum with MC methods at one end and one-step TD methods at the other. The best methods are often intermediate between the two extremes.”') },
    triad: { kind: 'failure', name: 'The deadly triad', short: 'Deadly triad', status: 'checked', paper: SB + ', section 11.3.',
      fixes: 'A failure: function approximation, bootstrapping and off-policy training together can make values diverge.',
      stillWrong: 'In this page: largest |Q| 4.7 million after 20000 steps, while no policy can earn more than 100 (3 seeds, Simulation). A 10 times smaller step size only slowed it (2300).',
      evidence: Q('Sutton and Barto 2018, section 11.3', '“the danger of instability and divergence arises whenever we combine all of the following three elements”: function approximation, bootstrapping, off-policy training. “If any two elements of the deadly triad are present, but not all three, then instability can be avoided.”') },
    dqn: { name: 'Deep Q-Network (DQN)', short: 'DQN', status: 'checked', paper: 'Mnih et al. (2015), Human-level control through deep reinforcement learning, <i>Nature</i> 518.', review: 'cartpole',
      fixes: 'Divergence of network Q-learning: random old moves break the chain of near-identical states, and the frozen copy holds the targets still between refreshes.',
      stillWrong: 'It overestimates action values on Atari (van Hasselt et al. 2016), needs many samples, and handles only discrete actions. In this page: 143 of 200 at 20000 steps (5 seeds, Simulation).',
      evidence: Q('Mnih et al. 2015', '“This instability has several causes: the correlations present in the sequence of observations, the fact that small updates to Q may significantly change the policy and therefore change the data distribution, and the correlations between the action-values (Q) and the target values”. Fix: experience replay, and “every C updates we clone the network Q to obtain a target network”.') },
    maxbias: { kind: 'failure', name: 'Maximization bias', short: 'Max bias', status: 'checked', paper: SB + ', section 6.7 and Example 6.7.',
      fixes: 'A failure: the max of noisy estimates is biased upward, so the learner prefers actions that only look good.',
      stillWrong: 'In this page: Q-learning took the left door in 66% of episodes at its worst point, against about 5% from random tries alone (300 runs, Simulation).',
      evidence: Q('Sutton and Barto 2018, Figure 6.5', '“Q-learning initially learns to take the left action much more often than the right action, and always takes it significantly more often than the 5% minimum probability enforced by ε-greedy action selection with ε = 0.1. In contrast, Double Q-learning is essentially unaffected by maximization bias.”') },
    doubleq: { name: 'Double Q-learning', short: 'Double Q', status: 'checked', paper: 'van Hasselt (2010), Double Q-learning, NeurIPS.', review: 'mirage',
      fixes: 'Maximization bias: one estimate chooses the best next action, the other, trained on other updates, scores it.',
      stillWrong: 'Each estimate learns from half of the updates. A frozen copy of the same table is not a second estimate: in this page it still went left 51% at its worst. Double Q: 9% (300 runs, Simulation).',
      evidence: Q('van Hasselt 2010, abstract and section 3', '“These overestimations result from a positive bias that is introduced because Q-learning uses the maximum action value as an approximation for the maximum expected action value.” “Double Q-learning stores two Q functions: QA and QB.”') },
    ddqn: { name: 'Double DQN', short: 'Double DQN', status: 'checked', paper: 'van Hasselt, Guez and Silver (2016), Deep Reinforcement Learning with Double Q-learning, AAAI.', review: 'cartpole',
      fixes: 'DQN overestimates: the live network chooses the next action and the frozen copy scores it.',
      stillWrong: 'The frozen copy is not fully independent of the live network. This toy CartPole does not overestimate, so the benefit does not show here: 137 against 143 for DQN (5 seeds, Simulation).',
      evidence: Q('van Hasselt, Guez and Silver 2016', '“DQN ... suffers from substantial overestimations in some games in the Atari 2600 domain.” Method: “evaluate the greedy policy according to the online network, but using the target network to estimate its value.” Limit: “Although not fully decoupled, the target network ... provides a natural candidate for the second value function”.') },
    clipped: { name: 'Clipped double Q', short: 'Clipped Q', status: 'checked', paper: 'Fujimoto, van Hoof and Meger (2018), Addressing Function Approximation Error in Actor-Critic Methods (TD3), ICML.', review: 'mirage',
      fixes: 'Overestimation in actor-critic methods: the target takes the smaller of two estimates.',
      stillWrong: 'It can underestimate; the paper prefers that to overestimation. Phase 3 (continuous control, SAC) uses it. In this page on the mirage: 8% left at the worst point (300 runs, Simulation).',
      evidence: Q('Fujimoto et al. 2018, section 4.2', '“taking the minimum between the two estimates, to give the target update of our Clipped Double Q-learning algorithm”. “While this update rule may induce an underestimation bias, this is far preferable to overestimation bias”.') },
  };

  const tree = {
    height: 450,
    nodes: { root: { x: 320, y: 24 }, egreedy: { x: 70, y: 104 }, optimism: { x: 196, y: 104 }, ucb: { x: 322, y: 104 }, mc: { x: 512, y: 104 },
      qlearning: { x: 512, y: 184 }, nstep: { x: 590, y: 264 }, sarsa: { x: 250, y: 264 }, expsarsa: { x: 110, y: 344 },
      dqn: { x: 400, y: 264 }, doubleq: { x: 560, y: 344 }, ddqn: { x: 400, y: 424 }, clipped: { x: 590, y: 424 } },
    edges: [['root', 'egreedy', 'lock-in'], ['root', 'optimism', 'lock-in'], ['root', 'ucb', 'lock-in'], ['root', 'mc', 'many steps'],
      ['mc', 'qlearning', 'no end'], ['mc', 'nstep', ''], ['qlearning', 'nstep', 'slow'], ['qlearning', 'sarsa', 'falls'], ['sarsa', 'expsarsa', 'noise'],
      ['qlearning', 'dqn', 'triad'], ['qlearning', 'doubleq', 'max bias'], ['dqn', 'ddqn', 'overestimate'], ['doubleq', 'ddqn', ''], ['doubleq', 'clipped', 'pessimism']],
  };

  const o = (steps, result, correct, why) => ({ steps, result, correct: !!correct, why });

  // which part of the sentence each level asks you to change ("focus")
  const levels = [
    {
      id: 'slots', world: 'bandit', title: 'Ten slot machines', seeds: 200, steps: 1000,
      start: cfg({ eps: false, step: 'avg' }), focus: ['eps', 'ucb', 'optimistic', 'step'],
      intro: 'Ten slot machines. Each has a hidden mean payout, drawn from a normal distribution N(0, 1). Each pull pays that mean plus noise with standard deviation 1. You get 1000 pulls. The learner keeps the average payout of each machine and always pulls the machine with the best average (greedy). All averages start at 0.',
      predict: { id: 'slots-p', prompt: 'After 1000 pulls, in what share of the last 200 pulls does greedy choose the best machine? (Mean of 200 independent runs.)', options: [
        o(['Every pull updates an average.', 'Averages converge to the true means (law of large numbers).', 'So the best machine gets the best average and greedy chooses it.'], 'Close to 100%.', 0,
          '<b>Wrong at step 2.</b> An average converges only for a machine that keeps being pulled. Greedy stops pulling the others, so their averages stay where they are.'),
        o(['At the start all averages are 0; a tie gives a random machine.', 'If that pull pays more than 0, its average is now above every other average (still 0).', 'Greedy keeps that machine until its average drops below 0, which may never happen.'], 'Often stuck on a machine that is not the best: about one run in three ends on the best one.', 1,
          'Each run locks on the first machine that paid well. That machine is better than average but usually not the best of ten. Measured in this page: 33% (300 runs, Simulation). Sutton and Barto report about one third.'),
        o(['The noise (standard deviation 1) is as large as the spread of the true means.', 'So the averages are mostly noise.', 'Greedy then chooses a machine at random.'], 'About 10% (1 in 10).', 0,
          '<b>Wrong at step 3.</b> The choice is not random: greedy keeps a machine that paid well early, so it does better than 1 in 10. With zero noise greedy still locks in (24% in this page).'),
      ] },
      runText: 'Run greedy on 200 independent sets of ten machines, 1000 pulls each. It takes about one second.',
      diagnose: { id: 'slots-d', prompt: 'The autopsy says the best machine gets about a third of the late pulls. What is the cause?', options: [
        o(['1000 pulls is too few.', 'More data improves every estimate.', 'Run 10 times longer.'], 'Cause: too short a budget.', 0,
          '<b>Wrong at step 2.</b> More pulls of the same machine do not improve the estimates of machines that are never pulled.'),
        o(['An estimate changes only when its machine is pulled.', 'Greedy never pulls a machine whose estimate is lower.', 'So one unlucky early payout is never corrected.'], 'Cause: no exploration.', 1,
          'The fix must make the learner try machines that do not look best now.'),
        o(['The payouts are noisy.', 'Noisy payouts give wrong averages.', 'Remove the noise and greedy finds the best machine.'], 'Cause: noise.', 0,
          '<b>Wrong at step 3.</b> With zero noise greedy still locks on the first machine with a positive mean. Try it in the Saboteur.'),
      ] },
      repairText: 'Change the words of the "act" line. At least three different sentences make the learner try machines that do not look best now.',
      hint: 'Look at the act line: random tries, a bonus for few tries, or a high start. With a high start, also look at the step word.',
      goal: { text: 'the best machine must get at least 70% of the last 200 pulls.', test: (a) => a.summary.optimalLast20 >= 0.7 },
      explain: { id: 'slots-x', prompt: 'Your fix worked. Why does it work?', options: [
        o(['The fix makes every machine get pulled again from time to time.', 'Each new pull corrects the average of a machine that had bad luck early.', 'So the best machine eventually shows the best average.'], 'Exploration corrects estimates that greedy never revisits.', 1, 'Every fix you can build here works this way: random tries, a bonus for few tries, or a start so high that every machine gets tried.'),
        o(['The fix lowers the noise of the payouts.', 'Less noise gives better averages.', 'So the best machine wins.'], 'It removes noise.', 0, '<b>Wrong at step 1.</b> No word changes the payouts. The world is the same; only the learner changed.'),
        o(['The fix makes the learner pull the best machine more often.', 'More pulls of the best machine make its average more exact.', 'So greedy finds it.'], 'It focuses on the best machine.', 0, '<b>Wrong at step 1.</b> The learner does not know which machine is best. The fix makes it pull the others more, not the best one.'),
      ] },
      soWhat: 'When a robot tunes one setting by trial, for example a gain, keeping the best value so far can lock in early. Plan some deliberate tries of values that do not look best yet.',
      cannotTeach: 'One state only, so no action changes what comes next. Real tasks have states, delays and a cost for each bad try.',
    },
    {
      id: 'cliff', world: 'cliff', title: 'The cliff edge', seeds: 20, steps: 10000,
      start: cfg({ nstep: 0 }), focus: ['nstep'], reveal: 'mc',
      intro: 'A grid, 4 rows by 12 columns. Start at bottom left, goal at bottom right. The bottom row between them is a cliff: a step into it costs −100 and sends you back to start. Every other step costs −1 (the setup of Example 6.6 in Sutton and Barto 2018, which is undiscounted; here γ = 0.99). An episode stops at the goal or after 200 steps. The learner uses a table and random tries (ε = 0.1). It waits until the episode ends, then moves each estimate toward the full return: the sum of the rewards that followed.',
      predict: { id: 'cliff-p', prompt: 'After 10000 steps, what does the greedy policy do from the start?', options: [
        o(['Each episode ends; the full return is a sample of the true value.', 'Samples are unbiased.', 'Unbiased values give the shortest safe path.'], 'It walks the optimal path: 13 steps, score −13.', 0,
          '<b>Wrong at step 1.</b> An episode cut by the 200-step limit gives the return of a partial walk, not the value of reaching the goal.'),
        o(['At first the walk is nearly random; reaching a goal 11 columns away inside 200 steps is rare.', 'So almost every episode ends at the time limit with a return of about −200 or worse, whatever the actions were.', 'The return does not say which step was bad, and cells never visited never get a value.'], 'It never learns the way to the goal; greedy wanders until the time limit (score −200).', 1,
          'Measured in this page: −200 in all 20 runs (Simulation).'),
        o(['The cliff costs −100.', 'The learner learns to avoid the cliff.', 'Away from the cliff, the top row leads to the goal.'], 'It finds the safe path along the top, about −17.', 0,
          '<b>Wrong at step 3.</b> Learning where the cliff is does not show where the goal is. That information never arrives.'),
      ] },
      runText: 'Run the full-return learner on the cliff: 20 runs of 10000 steps.',
      diagnose: { id: 'cliff-d', prompt: 'Score −200: no greedy path to the goal. Which change gives a learning signal during the episode?', options: [
        o(['After each step you know the reward r and the next state s′.', 'Your own estimate of s′ already summarizes what follows s′.', 'So move Q(s,a) toward r + γ·(estimate at s′) now, without waiting.'], 'Learn during the episode from a guess.', 1,
          'This is bootstrapping: a guess is updated from another guess. It needs no episode end.'),
        o(['The learner explores too little.', 'Raise ε to 0.3.', 'More random steps reach the goal and fix the values.'], 'More exploration.', 0,
          '<b>Wrong at step 3.</b> With ε = 0.3 it still scored −199 in this page (20 runs). The return still mixes all steps together.'),
        o(['The time limit is too short.', 'Raise it to 500 steps.', 'Then episodes reach the goal.'], 'A longer time limit.', 0,
          '<b>Wrong at step 3.</b> With a 500-step limit it scored −500 in this page (20 runs): the walk rarely reaches the goal, and each return mixes hundreds of steps.'),
      ] },
      repairText: 'Change how many real rewards the learner uses before it trusts a guess.',
      hint: 'The word "all rewards to the end" means no guess at all. Try a small number.',
      goal: { text: 'the greedy score must reach −20 or better (the optimum is −13).', test: (a) => a.summary.finalReturn >= -20 },
      explain: { id: 'cliff-x', prompt: 'With 1 real reward and then a guess, the table found the 13-step path. Where did the information about the goal come from?', options: [
        o(['Unvisited cells keep their start value 0.', 'Each step costs −1, so 0 looks better than any visited cell.', 'The guess at s′ pulls the learner toward unvisited cells, one step at a time, until one of them is the goal.'], 'From the guesses: the zero start is optimistic here, and each guess passes value one step back.', 1, 'The full return never used the zero estimates of unvisited cells. The guess does, so it explores and passes the goal value back one step per update.'),
        o(['The learner now reaches the goal by luck more often.', 'Each lucky episode gives a good return.', 'Good returns teach the path.'], 'From more lucky episodes.', 0, '<b>Wrong at step 3.</b> The guess-based learner does not wait for returns at all. It learns inside each episode, from each step.'),
        o(['The guess uses the true value of the next state.', 'True values show the goal.', 'So the path follows.'], 'From true values.', 0, '<b>Wrong at step 1.</b> The guess is the learner\'s own estimate, not the true value. It starts wrong and improves.'),
      ] },
      soWhat: 'One attempt at a robot task, for example one drawing pass, is a long episode. If the only feedback is a score at the end of the pass, every stroke shares the blame for everything after it. A per-step value estimate (a critic) gives feedback inside the pass.',
      cannotTeach: 'Every state fits in a table here. A real arm has continuous joint angles, so a table does not fit; see a later level.',
    },
    {
      id: 'careful', world: 'cliff', title: 'Falling while learning', seeds: 20, steps: 10000,
      start: cfg({}), focus: ['agg', 'nstep'],
      intro: 'Q-learning found the 13-step path along the cliff edge. But the learner still takes random actions (ε = 0.1) while it learns. A real arm learns on the real table: every fall while learning is a real crash. Measured in this page: 0.32 falls per episode in the second half of training.',
      predict: { id: 'careful-p', prompt: 'Q-learning uses "the best next action" in its guess. It still takes a random action 10% of the time. Which path do its estimates prefer?', options: [
        o(['The guess assumes the best next action is always taken.', 'If every next action is the best one, the edge is safe.', 'So the estimates prefer the shortest path, right along the edge.'], 'The edge path, and the random tries push it over the edge.', 1, 'That is the gap: it plans for a learner that never slips, but it slips 10% of the time.'),
        o(['The cliff costs −100.', 'Q-learning sees the −100 many times.', 'So it moves away from the edge.'], 'A safe path away from the edge.', 0, '<b>Wrong at step 3.</b> The −100 is in the estimate of stepping into the cliff, but the guess uses only the best next action, which never steps in.'),
        o(['ε = 0.1 is small.', 'Small random tries do not matter.', 'So falls are rare.'], 'Almost no falls.', 0, '<b>Wrong at step 2.</b> Along the edge, one random "down" in 13 steps is enough to fall. 0.32 falls per episode were measured.'),
      ] },
      runText: 'Run Q-learning on the cliff and read the falls in the autopsy.',
      diagnose: { id: 'careful-d', prompt: 'Which word makes the estimates ignore the random tries?', options: [
        o(['The guess uses "the best next action".', 'The learner does not always take the best action.', 'So the guess values a learner that does not exist.'], 'The next-action word of the guess.', 1, 'Change it to an action the learner really takes, or to an average over what it takes.'),
        o(['The step is too large.', 'A large step follows noise.', 'Use a smaller step.'], 'The step size.', 0, '<b>Wrong at step 3.</b> A smaller step learns the same edge path more slowly.'),
        o(['Random tries cause the falls.', 'Turn random tries off.', 'Then there are no falls.'], 'The random tries.', 0, '<b>Not allowed here:</b> a real arm must keep exploring to improve. Keep random tries on and change what the guess assumes.'),
      ] },
      repairText: 'Keep "sometimes at random". Change what the guess assumes about the next action.',
      hint: 'Two next-action words describe what the learner really does: the action really taken next, or the average next action.',
      goal: { text: 'fewer than 0.1 falls per episode in the second half, with random tries still on.', test: (a, p) => p.eps && a.summary.fallsPerEpisode < 0.1 },
      notes: [
        { when: (a) => a.summary.fallsPerEpisode < 0.1 && a.summary.finalReturn < -20, text: 'Fewer falls, but the greedy path is unstable: score {final}. Its target depends on one random next action. One other next-action word gives a steadier target. Pin this run as A and compare.' },
      ],
      explain: { id: 'careful-x', prompt: 'Your new sentence falls less while it learns. Why does it keep away from the edge?', options: [
        o(['Near the edge, the learner sometimes takes a random "down" next.', 'The new target includes what really happens after its own moves, so some of those targets contain the −100.', 'So edge cells get lower values, and a path one row up looks better.'], 'The target includes the cost of its own random tries.', 1, 'This is on-policy learning: it values the policy it really follows, random tries included. "The action really taken next" and "the average next action" do it inside the guess. Several real rewards do it partly, because those rewards come from the moves it really made.'),
        o(['It explores less.', 'Less exploration means fewer falls.', 'So it is safer.'], 'It explores less.', 0, '<b>Wrong at step 1.</b> ε is still 0.1. The learner acts the same way; it values the actions differently.'),
        o(['It learns the true values faster.', 'True values show that the edge is dangerous.', 'So it avoids the edge.'], 'Faster learning.', 0, '<b>Wrong at step 2.</b> For a learner that never slips, the edge is not dangerous. The danger exists only because of the random tries.'),
      ] },
      soWhat: 'On a real arm, you pay for the moves you make while learning. A learner that values its own exploration (on-policy) chooses safer moves near limits, for example near joint limits or the paper edge.',
      cannotTeach: 'Falls here cost only reward. A real crash can damage the arm, which no reward value captures.',
    },
    {
      id: 'cells', world: 'cartpole', title: 'Too many cells', seeds: 3, steps: 20000,
      start: cfg({}), focus: ['store'],
      intro: 'CartPole: push a cart left or right to keep a pole up. The state is 4 sensor numbers: cart position, cart speed, pole angle, pole speed. Reward +1 per step; the time limit is 200 steps. A table cuts each sensor into 6 bins: 6⁴ = 1296 cells, each with its own two estimates. Budget: 20000 steps.',
      predict: { id: 'cells-p', prompt: 'Q-learning solved the cliff. How well does the table balance the pole after 20000 steps?', options: [
        o(['Q-learning worked in a table on the cliff.', '1296 cells is a small table.', 'So it converges and balances to the limit.'], 'About 200 of 200.', 0,
          '<b>Wrong at step 2.</b> Small in memory, but 20000 steps over 1296 cells is about 15 visits per cell on average, far fewer for rare cells.'),
        o(['20000 steps over 1296 cells is about 15 visits per cell, far fewer for rare cells.', 'A cell learns nothing from its neighbors, even when they hold almost the same state.', 'Many cells stay near their start value.'], 'It balances only part of the time, well under 200.', 1,
          'Measured in this page: 50 of 200 (5 seeds, Simulation).'),
        o(['Bins merge different states.', 'Merged states can need different actions.', 'So a table can never balance.'], 'Near 10: it falls at once.', 0,
          '<b>Wrong at step 3.</b> Coarse bins lose detail but still balance for a while. Even a 3-bin table balanced longer than 6 bins in this page.'),
      ] },
      runText: 'Run the table: 3 seeds of 20000 steps.',
      diagnose: { id: 'cells-d', prompt: 'The table scores about 50 of 200. What limits it most?', options: [
        o(['The bins are too coarse.', 'Use 12 bins per sensor.', 'Finer cells give a better policy.'], 'Not enough resolution.', 0,
          '<b>Wrong at step 3.</b> 12 bins give 20736 cells, each visited even less. It did not do better in this page. Try it in the Saboteur.'),
        o(['Neighbor cells hold almost the same state.', 'A table cannot pass what one cell learned to its neighbors.', 'So every cell must be visited many times.'], 'No sharing between similar states.', 1,
          'The remedy is a store where similar states share what they learn.'),
        o(['ε-greedy explores at random.', 'Random pushes make the pole fall.', 'So the data is useless.'], 'Too much exploration.', 0,
          '<b>Wrong at step 3.</b> Falls are useful data: they show which states lead to a fall. The table cannot use that data in other cells.'),
      ] },
      repairText: 'Change where the estimates live. Then run and watch the third chart (largest |Q|).',
      hint: 'Change the store word to a network. Keep the other words.',
      goal: { text: 'run the sentence with "a network".', test: (a, p) => p.store === 'net' },
      explain: null,
      soWhat: 'A network shares across similar states, so it needs far fewer visits. The price: one update moves many estimates at once, including the ones it uses as its own targets.',
      cannotTeach: 'Four clean numbers. A real arm adds motor delay, backlash and a camera; a real network would also need to handle those.',
    },
    {
      id: 'explode', world: 'cartpole', title: 'Values explode', seeds: 3, steps: 20000,
      start: cfg({ store: 'net' }), focus: ['data', 'picker', 'scorer', 'sync', 'nstep'],
      intro: 'You swapped the table for a network. The largest estimate went to millions. With reward 1 per step and γ = 0.99, no policy can earn more than 1 / (1 − 0.99) = 100.',
      predict: { id: 'explode-p', prompt: 'The update moves Q(s,a) toward r + γ·max Q(s′). In CartPole, consecutive states s and s′ are almost the same. One update raises Q(s,a). What happens next?', options: [
        o(['The reward is at most 1.', 'So every target is at most 1 + γ·Q(s′).', 'That bound keeps Q below 100.'], 'Nothing: the values stay bounded.', 0,
          '<b>Wrong at step 3.</b> The bound holds only if Q(s′) is already bounded. If Q(s′) rises, the bound rises with it.'),
        o(['The network shares weights, so raising Q(s,a) also raises Q at the nearby state s′.', 'The target r + γ·max Q(s′) is now higher.', 'The next update chases the higher target, which raises Q(s′) again.'], 'A loop that can push the values up without limit.', 1,
          'The learner chases a target that moves with it. Watch it happen in "Watch one update".'),
        o(['Adam (the optimizer) keeps each step small.', 'Small steps cannot blow up.', 'So only the policy changes, not the size of Q.'], 'Small, safe changes.', 0,
          '<b>Wrong at step 2.</b> Many small steps in the same direction add up. With a 10 times smaller step size the values still reached 2300 in this page.'),
      ] },
      runText: 'Run the network sentence again and watch the third chart (largest |Q|, log scale).',
      diagnose: { id: 'explode-d', prompt: 'Which three ingredients together make this loop?', options: [
        o(['The step size is too large.', 'Large steps overshoot.', 'Lower the step size 10 times.'], 'Too large a step size.', 0,
          '<b>Wrong at step 3.</b> A smaller step only slows the loop: 2300 instead of 4.7 million in this page (3 seeds).'),
        o(['A store that shares between states (function approximation).', 'A target made from its own estimate (bootstrapping).', 'Data from moves that are not the moves the target assumes (off-policy: random tries, best-action target).'], 'Function approximation + bootstrapping + off-policy data.', 1,
          'Sutton and Barto call this combination the deadly triad. Removing or weakening one leg stops the loop.'),
        o(['ε-greedy takes random moves.', 'Random moves make bad data.', 'Turn exploration off.'], 'Exploration.', 0,
          '<b>Wrong at step 3.</b> Without exploration the learner stops seeing new states; the network and the bootstrap still feed each other.'),
      ] },
      repairText: 'Break the loop. You can change which moves it learns from, which estimate chooses and scores the next action, and how many real rewards it uses. Many sentences work; some only look like a fix. Use "Pin as A" to compare two sentences.',
      hint: 'Two separate ideas each weaken the loop: make the target come from an estimate that does not move with every update, and stop learning only from the newest move (its neighbor states are almost the same).',
      goal: { text: 'no blow-up (largest |Q| below 1000) and a final score of 100 or more.', test: (a) => !a.symptoms.some((s) => s.id === 'diverge') && a.summary.finalReturn >= 100 },
      explain: { id: 'explode-x', prompt: 'A frozen copy scores the next action, and the learner learns from random old moves. Why do the values stay bounded now?', options: [
        o(['The frozen copy does not change when the live network updates.', 'So raising Q(s,a) does not raise the target for the next updates.', 'Random old moves come from many different states, so one update does not keep pushing the same neighbors.'], 'The target stops moving with each update, and the updates stop chaining through neighbors.', 1, 'In "Watch one update", the frozen target stays the same after the update while the live estimate at s′ moves.'),
        o(['The frozen copy is more accurate.', 'Accurate targets cannot blow up.', 'So the values stay bounded.'], 'A more accurate target.', 0, '<b>Wrong at step 1.</b> The frozen copy is older, so it is usually less accurate. Its value is that it holds still.'),
        o(['Replay gives more data.', 'More data lowers the variance.', 'Lower variance stops the blow-up.'], 'More data.', 0, '<b>Wrong at step 2 to 3.</b> Replay alone still blew up in this page (largest |Q| 110 000). Variance is not the loop; the moving target is.'),
      ] },
      soWhat: 'If you train a critic for a real arm with bootstrapped targets, plot the largest estimate against the largest return the arm can earn. A frozen target copy is cheap insurance.',
      cannotTeach: 'CartPole episodes are short and always end, so the full return also works here (196 of 200 with replay, 3 seeds, Simulation). A long or endless task does not give that option.',
    },
    {
      id: 'mirage', world: 'mirage', title: 'The mirage', seeds: 300, steps: 600,
      start: cfg({}), focus: ['picker', 'scorer', 'agg'],
      intro: 'Two states. In state A, the right door ends the episode with reward 0. The left door leads to state B with reward 0. In B there are 10 machines; each pays a random amount with mean −0.1 and standard deviation 1, then the episode ends. So the left door loses 0.1 on average. Q-learning, ε = 0.1, step size 0.1, no discount. This is the setup of Example 6.7 in Sutton and Barto (2018); the book says “many” actions in B, this page uses 10.',
      predict: { id: 'mirage-p', prompt: 'In the early episodes, how often does Q-learning take the left door? (With ε = 0.1, random tries alone take it about 5% of the time.)', options: [
        o(['The true value of the left door is −0.1.', 'Q-learning estimates values.', 'So it sees that left is worse and goes right.'], 'About 5%: only random tries.', 0,
          '<b>Wrong at step 2.</b> The target for the left door is the max over the 10 machine estimates, not their mean.'),
        o(['After a few payouts, some machine estimates are above 0 by luck.', 'The target for the left door is r + max over the 10 machine estimates, and the max takes the lucky one.', 'So Q(A, left) looks positive.'], 'Left most of the time at first, far above 5%.', 1,
          'Measured in this page: 66% of episodes at the worst point (300 runs, Simulation).'),
        o(['10 machines average out the noise.', 'The average of 10 has noise 1 / √10.', 'Small noise gives a small bias.'], 'About 10%.', 0,
          '<b>Wrong at step 1.</b> The target takes the max over the machines, not their average. More machines make the max larger, not smaller.'),
      ] },
      runText: 'Run Q-learning on the mirage: 300 runs of 600 steps (about 300 episodes).',
      diagnose: { id: 'mirage-d', prompt: 'Where does the upward bias come from?', options: [
        o(['The step size 0.1 is too large.', 'Large steps follow lucky payouts.', 'A smaller step removes the bias.'], 'The step size.', 0,
          '<b>Wrong at step 3.</b> A smaller step averages more payouts per estimate, but the max over 10 noisy estimates is still above their true max.'),
        o(['The same noisy estimates choose the best machine.', 'And the same estimates give its value.', 'A machine chosen for its lucky estimate is then scored by that lucky estimate.'], 'One estimate both chooses and scores.', 1,
          'The fix: choose with one estimate and score with another one whose noise is independent.'),
        o(['ε = 0.1 explores too little.', 'More exploration samples every machine more.', 'More samples remove the bias.'], 'Too little exploration.', 0,
          '<b>Wrong at step 3.</b> More samples shrink the bias over time, but the early chase still happens; the bias comes from the max itself.'),
      ] },
      repairText: 'Change which estimate chooses the next action and which one scores it. One choice only looks like a fix.',
      hint: 'A frozen copy of the same table is made from the same lucky payouts. You need an estimate trained on different payouts. "The average next action" does not help either (59% in this page).',
      goal: { text: 'the left door must stay below 25% of episodes at the worst point.', test: (a) => a.summary.leftPeak < 0.25 },
      explain: { id: 'mirage-x', prompt: 'A second estimate scores the machine that the live estimate chooses. Why does the bias go away?', options: [
        o(['The live estimate chooses the machine that looks best, often a lucky one.', 'The second estimate was trained on other payouts, so its error on that machine is independent.', 'On average its value for that machine is the true mean, −0.1.'], 'Independent noise: the luck that chose the machine does not also score it.', 1, 'That is why a frozen copy fails: it was made from the same lucky payouts (51% left in this page).'),
        o(['Two estimates average out the noise.', 'Averaged noise is smaller.', 'So the max is smaller.'], 'Averaging.', 0, '<b>Wrong at step 1.</b> Nothing is averaged in the target; one estimate chooses, the other scores.'),
        o(['The second estimate is pessimistic.', 'Pessimism lowers every value.', 'So left looks bad.'], 'Pessimism.', 0, '<b>Wrong at step 1.</b> The second estimate is not pessimistic by itself. "The smaller of live and second" is the pessimistic word; it also works here (8%).'),
      ] },
      soWhat: 'If a robot chooses a command as the max of a learned score over many candidates (a Q-scorer, or an ensemble), the max prefers candidates with lucky errors. Score the winner with a second, independent model.',
      cannotTeach: 'Two states only. It shows the sign of the bias, not its size in a large network on a long task.',
    },
  ];

  const missions = [
    { id: 'noise0', world: 'bandit', parts: cfg({ eps: false, step: 'avg' }), title: 'Clear the noise',
      text: 'Greedy locks in. Is noise to blame? Set the payout noise to 0 and run. If greedy still locks in, noise was not the cause.',
      goalText: 'Goal: greedy still chooses the best machine less than half of the time, with noise 0.',
      test: (a, k) => a.summary.optimalLast20 < 0.5 && k.noise === 0,
      lesson: 'With zero noise greedy still locks in (24% in this page): the cause is the lack of exploration, not the noise.' },
    { id: 'drift', world: 'bandit', parts: cfg({ step: 'avg' }), title: 'Machines that change',
      text: 'ε-greedy with averages finds the best machine 78% of the time. Make the machines change while it plays (drift) until it loses track.',
      goalText: 'Goal: best machine below 60% of the late pulls.',
      test: (a) => a.summary.optimalLast20 < 0.6,
      lesson: 'An average over all past pulls cannot follow a machine that changes. Change the step word to "a fixed share (α)": in this page it went from 53% to 71% at drift 0.03. Your servo heats up and its friction changes: old data can mislead in the same way.' },
    { id: 'starve', world: 'cartpole', parts: cfg({ store: 'net', data: 'replay', picker: 'frozen', scorer: 'frozen' }), title: 'Starve DQN',
      text: 'DQN balances CartPole. Take its reward away until it learns nothing.',
      goalText: 'Goal: the greedy policy never earns a reward (final score 0).',
      test: (a) => a.summary.finalReturn === 0,
      lesson: 'With a reward only at the time limit, most training episodes give no reward at all (2% to 11% had one in this page, 3 seeds), so almost every target is 0. A real arm has the same risk if the only reward is "the drawing is right" at the end.' },
    { id: 'shake', world: 'cartpole', parts: cfg({ store: 'net', data: 'replay', picker: 'frozen', scorer: 'frozen' }), title: 'Shake the sensors',
      text: 'Add sensor noise until DQN cannot balance any more.',
      goalText: 'Goal: final score below 100 of 200.',
      test: (a) => a.summary.finalReturn < 100,
      lesson: 'Noise 0.5 dropped DQN to 44 of 200 in this page. The network sees a different state from the true one; a filter or a state estimator (an observer) must clean the signal first.' },
    { id: 'bins', world: 'cartpole', parts: cfg({}), title: 'Finer is slower',
      text: 'Change the number of table bins. Make the table worse by making it more precise.',
      goalText: 'Goal: final score below 50 of 200 (the 6-bin table scores 51) with more than 6 bins.',
      test: (a, k) => a.summary.finalReturn < 50 && k.bins > 6,
      lesson: 'More bins mean more cells, and each cell gets fewer visits: 12 bins scored 46 and 3 bins scored 97, against 51 for 6 bins (3 seeds each, Simulation). Resolution costs data.' },
    { id: 'bigger', world: 'mirage', parts: cfg({}), title: 'A bigger mirage',
      text: 'Make the mirage stronger: change the number of machines and the payout noise.',
      goalText: 'Goal: left door in more than 90% of episodes at the worst point.',
      test: (a) => a.summary.leftPeak > 0.9,
      lesson: 'More actions and more noise give the max more lucky estimates to choose from: 20 machines with noise 2 gave 94%. Double Q-learning stayed at 15% (Simulation).' },
    { id: 'slip', world: 'cliff', parts: cfg({}), title: 'A slippery edge',
      text: 'Q-learning walks the cliff edge. Make the actuator slip until that path costs it.',
      goalText: 'Goal: greedy score worse than −50.',
      test: (a) => a.summary.finalReturn < -50,
      lesson: 'Q-learning learns the path that is best if every action works. With slip 0.2 the edge path fell often (score −96 in this page). The level "Falling while learning" shows learners that value the moves they really make.' },
  ];

  // when a sentence "works" in a world, its name appears
  const works = {
    bandit: (a) => a.summary.optimalLast20 >= 0.7,
    cliff: (a) => a.summary.finalReturn >= -20 || (a.summary.fallsPerEpisode < 0.1 && a.summary.peak >= -20),
    cartpole: (a) => !a.symptoms.some((s) => s.id === 'diverge') && a.summary.finalReturn >= 100,
    mirage: (a) => a.summary.leftPeak < 0.25,
  };

  return {
    words, base, cfg, recipes, failures, cards, tree, levels, missions, works,
    worldNames: { bandit: 'Ten slot machines', cliff: 'Cliff walking', cartpole: 'CartPole', mirage: 'The mirage' },
    budgets: { bandit: [1000, 2000], cliff: [5000, 10000, 20000], cartpole: [10000, 20000, 40000], mirage: [600, 1200] },
    budgetDefault: { bandit: 0, cliff: 1, cartpole: 1, mirage: 0 },
    seedOptions: { bandit: [50, 200, 300], cliff: [5, 20], cartpole: [1, 3, 5], mirage: [100, 300] },
    hyper: {
      bandit: { epsStart: 0.1, epsEnd: 0.1, lrTable: 0.1 },
      mirage: { epsStart: 0.1, epsEnd: 0.1, lrTable: 0.1 },
      cliff: { epsStart: 0.1, epsEnd: 0.1, lrTable: 0.5 },
      cartpole: {},
    },
    chatHello: 'I am the lab assistant. Ask me about a result, or ask me to set up an experiment. I will ask you to predict before I run it.',
  };
})();
